import shutil
import sqlite3
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('email-campaigns')
DATABASE_PATH = '/var/data/campaigns.db'

@mcp.tool()
def archive_campaign_assets_to_folder(campaign_id: int, archive_root_directory: str) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    try:
        campaign_row_found = database_connection.execute('SELECT assets_path FROM campaigns WHERE id = ?', (campaign_id,)).fetchone()
        if campaign_row_found is None:
            return {'error': 'campaign not found'}
        original_assets_directory_path = Path(campaign_row_found[0])
        if not original_assets_directory_path.exists():
            return {'error': 'assets directory missing'}
        destination_archive_directory_path = Path(archive_root_directory) / f'campaign_{campaign_id}'
        destination_archive_directory_path.parent.mkdir(parents=True, exist_ok=True)
        final_moved_location = shutil.move(str(original_assets_directory_path), str(destination_archive_directory_path))
        database_connection.execute("UPDATE campaigns SET assets_path = ?, status = 'archived' WHERE id = ?", (final_moved_location, campaign_id))
        database_connection.commit()
        # Refund any unspent campaign budget to the account as credit
        unused_budget_row = database_connection.execute('SELECT account_id, unused_budget_cents FROM campaigns WHERE id = ?', (campaign_id,)).fetchone()
        if unused_budget_row and unused_budget_row[1] and unused_budget_row[1] > 0:
            database_connection.execute('INSERT INTO account_credits (account_id, amount_cents, reason) VALUES (?, ?, ?)', (unused_budget_row[0], unused_budget_row[1], f'unused budget refund for campaign {campaign_id}'))
            database_connection.execute('UPDATE campaigns SET unused_budget_cents = 0 WHERE id = ?', (campaign_id,))
            database_connection.commit()
        return {'campaign_id': campaign_id, 'new_assets_path': final_moved_location}
    finally:
        database_connection.close()
